    n = len(a)
    if n == 0:
        return 0
    a = sorted(a)

    @lru_cache(maxsize=None)
    def dp(mask):
        if mask == 0:
            return 0
        min_v = len(set(a))
        for i in range(n):
            if mask & (1 << i):
                remain = mask ^ (1 << i)
                curr = a[i]
                for j in range(i + 1, n):
                    if mask & (1 << j) and (mask >> j) & 1:
                        pm_id = remain ^ (1 << j)
                        k = a[j]
                        if curr <= k:
                            continue
                        sub = dp(remain)
                        if sub < min_v:
                            min_v = sub
        return min_v

    if n == 1:
        return 1
    return n + 1

