    return C

def mat_pow(A, p):
    res = [[0]*4 for _ in range(4)]
    for i in range(4):
        res[i][i] = 1
    while p > 0:
        if p & 1:
            res = mat_mul(res, A)
        A = mat_mul(A, A)
        p >>= 1
    return res

def fast_pow(a, b):
    res = 1
    while b:
        if b & 1:
            res = (res * a) % MOD
        a = (a * a) % MOD
        b >>= 1
    return res

