    if n <= 2:
        return '0'

    # Use a segment tree to efficiently query and update minimums
    # Tree size should be power of 2 for easier implementation
    size = 1
    while size < n:
        size *= 2

    # 4 * size is safe upper bound
    tree_min = [float('inf')] * (4 * size)
    tree_idx = [-1] * (4 * size)

    def update_min(node, l, r, x):
        mid = (l + r) // 2
        if x < tree_min[node]:
            tree_min[node] = x
            tree_idx[node] = x
        if l == r:
            return
        if l <= mid:
            update_min(2 * node, l, mid, x)
        if mid + 1 <= r:
            tree_idx[2 * node + 1] = x

    def query_min(node, l, r):
        if tree_idx[node] != -1:
            return tree_idx[node]
        if l == r:
            return tree_idx[2 * node + 1]
        if l <= (r - l) // 2:
            return query_min(2 * node, l, l + (r - l) // 2)
        return query_min(2 * node + 1, l + (r - l) // 2 + 1, r)

    def update_idx(node, l, r, idx, val):
        if l == r:
            tree_idx[node] = val
        else:
            mid = (l + r) // 2
            if idx <= mid:
                update_idx(2 * node, l, mid, idx, val)
            else:
                update_idx(2 * node + 1, mid + 1, r, idx, val)
        tree_min[node] = tree_min[2 * node]
        tree_idx[node] = tree_idx[2 * node]

    for i in range(n):
        update_idx(1, 0, size - 1, i, a[i])

    def build_heap():
        heap = []
        for i in range(1, n):
            if not (i == 0 or i == n - 1):
                val = min(a[i - 1], a[i + 1])
                heap.append((val, i))
        heapq.heapify(heap)
        return heap

    heap = build_heap()
    total = 0

    while heap:
        val, idx = heapq.heappop(heap)
        left = idx
        right = idx
        total += min(a[left], a[right])
        heapq.heappush(heap, (min(a[left - 1], a[right + 1]), idx))

    return str(total)

