def solution(input_str: str) -> str:
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    edges = []
    for i in range(m):
        parts = lines[i + 1].split()
        a, b, e = int(parts[0]), int(parts[1]), int(parts[2])
        edges.append({'u': a, 'v': b, 'idx': i, 'w': e})

    # Kruskal's MST
    sorted_edges = sorted(edges, key=lambda x: x['w'])
    parent = list(range(n + 1))
    def find(x):
        while parent[x] != x:
            parent[x] = find(parent[x])
            x = parent[x]
        return x

    mst_adj = [[] for _ in range(n + 1)]
    in_mst = [False] * m
    cnt = 0

    for edge in sorted_edges:
        if cnt == n - 1:
            break
        u, v, idx, w = edge['u'], edge['v'], edge['idx'], edge['w']
        root_u, root_v = find(u), find(v)
        if root_u != root_v:
            parent[root_u] = root_v
            in_mst[idx] = True
            mst_adj[u].append((v, w))
            mst_adj[v].append((u, w))
            cnt += 1

    # Extract non-MST edges
    non_mst = []
    for edge in edges:
        if not in_mst[edge['idx']]:
            non_mst.append(edge)

    if len(non_mst) == 0:
        return ""

    # Binary lifting on MST
    LOG = 20
    up = [[0] * (n + 1) for _ in range(LOG)]
    max_val = [[0] * (n + 1) for _ in range(LOG)]

    stack = [(1, 1, 0)]
    order = []

    capacity = {}

    while stack:
        u, p, w = stack.pop()
        order.append(u)
        if p != 1:
            capacity[u] = max_val[0][p]
            capacity[p] = max_val[0][p]
        up[0][u] = p
        max_val[0][u] = w
        for v, weight in mst_adj[u]:
            if v != p:
                stack.append((v, u, weight))

    for i in range(1, LOG):
        for u in range(1, n + 1):
            if up[i - 1][u] != 0:
                up[i][u] = up[i - 1][up[i - 1][u]]
                max_val[i][u] = max(max_val[i - 1][u], max_val[i - 1][up[i - 1][u]])

    results = []
    for edge in non_mst:
        u, v = edge['u'], edge['v']
        res = u ^ v
        diff = u ^ res
        diff2 = v ^ res
        ans = 0
        for i in range(LOG):
            if (diff >> i) & 1:
                if res > 1:
                    ans = max(ans, max_val[i][res - 1] + max_val[i][up[i][res]])
    results.append(ans)

    return "\n".join(map(str, results))

