MOD = 10**9 + 7

class Parser:
    def __init__(self, s: str):
        self.s = s
        self.pos = 0

    def skip_ws(self):
        while self.pos < len(self.s) and self.s[self.pos].isspace():
            self.pos += 1

    def peek(self):
        if self.pos < len(self.s):
            return self.s[self.pos]
        return None

    def advance(self):
        self.pos += 1

    def read_until(self, stop: List[str]) -> str:
        start = self.pos
        while self.pos < len(self.s):
            b = self.s[self.pos]
            if b in stop:
                break
            self.pos += 1
        return self.s[start:self.pos]

    def parse_number(self) -> Tuple[int, str]:
        start, l = self.pos, 0
        neg = False
        if self.s[self.pos] == '-':
            neg = True
            self.pos += 1
            l = 1
        while self.s[self.pos] != None and self.s[self.pos] in '0123456789':
            self.pos += 1
            l += 1
        if pos == start + (0 if not neg else 1):
            raise ValueError("Invalid number")
        num_str = self.s[start:self.pos]
        return num_str, neg

    def parse_expression(self) -> int:
        value = self.parse_term()
        while self.s[self.pos] == '+':
            self.pos += 1
            next_val = self.parse_term()
            value = (value + next_val) % MOD
        return value

    def parse_term(self) -> int:
        if self.s[self.pos] == '-' or self.s[self.pos] == '(':
            raise ValueError("Unexpected character")

        ls_buf = self.read_until(['-', '('])
        ls = self.parse_number()

        if self.s[self.pos] == '-':
            self.pos += 1
            rs_buf = self.read_until(['-', '(', '+', '\n'])
            rs = self.parse_number()
            return self.compute_range(ls, rs)

        if self.s[self.pos] == '(':
            self.pos += 1
            expr_val = self.parse_expression()
            self.s += self.parse_number()
            self.advance()
            return self.repeat_expr(ls, expr_val)

        return ls

def compute_range(l_str: str, r_str: str) -> int:
    l = int(l_str)
    r = int(r_str)
    return concat_range(l, r)

def concat_range(l: int, r: int) -> int:
    MOD = 10**9 + 7
    if l > r:
        return 0
    if l == r:
        return l % MOD

    cnt = r - l + 1
    if cnt > MOD:
        cnt %= MOD

    result = 0
    pos = l
    while pos <= r:
        result = (result * pow(10, len(str(pos)), MOD) + pos) % MOD
        pos += 1
        if pos > r:
            break
    return result

def repeat_expr(k: int, expr: int) -> int:
    if k == 0 or expr == 0:
        return 0
    cnt = int(str(expr))
    return (expr * pow(10, (cnt - 1) * len(str(k)), MOD)) % MOD

def solution(s: str) -> str:
    parser = Parser(s)
    parser.skip_ws()
    val = parser.parse_expression()
    result = str(val)
    return result

