                        char_index = ord(s1[i]) - ord('A')
                        new_state = transition[state][char_index]
                        if new_state < k:
                            new_len = dp[i][j][state] + 1
                            dp[i + 1][j + 1][new_state] = max(dp[i + 1][j + 1][new_state], new_len)
                            choice[i + 1][j + 1][min(new_state, k - 1)] = min(choice[i + 1][j + 1][min(new_state, k - 1)], 2)

    # Find max length
