def get_square_free_part(n):
    result = 1
    divisor = 2
    while divisor * divisor <= n:
        if n % divisor == 0:
            count = 0
            while n % divisor == 0:
                n //= divisor
                count += 1
            if count % 2 == 1:
                result *= divisor
        divisor += 1
    if n > 1:
        result *= n
    return result

def factorial(n):
    res = 1
    for i in range(2, n + 1):
        res = (res * i) % MOD
    return res

def inverse(n):
    return pow(n, MOD - 2, MOD)

def nCr(n, r):
    if r > n or r < 0:
        return 0
    num = factorial(n)
    den = (factorial(r) * factorial(n - r)) % MOD
    return (num * inverse(den)) % MOD

