            if x * x + y * y <= r * r:
                points.append((x, y))

    best_score = -1
    best_combo = None

    for combo in itertools.combinations(points, n):
        score = compute_score(combo, n)
        if score > best_score:
            best_score = score
            best_combo = combo

    lines = [str(best_score)]
    for x, y in best_combo:
        lines.append(f"{x} {y}")
    return "\n".join(lines)

def rev(x):
    return int(str(x)[::-1])

def is_lucky(a, b):
    return a * b == rev(a) * rev(b)

def solution(input_str):
    import sys
    input_str = input_str.strip()
    if not input_str:
        return "-1"
    parts = input_str.split()
    if len(parts) < 3:
        return "-1"
    try:
        maxx = int(parts[0])
        maxy = int(parts[1])
        w = int(parts[2])
    except (ValueError, IndexError):
        return "-1"

    # Generate all lucky pairs
    # Group by 'a' (series number)
    from collections import defaultdict
    lucky_by_a = defaultdict(list)

    for a in range(1, maxx + 1):
        for b in range(1, maxy + 1):
            if is_lucky(a, b):
                lucky_by_a[a].append(b)

    # Precompute prefix counts
    # For each a, we have list of b's
    all_lucky = []
    for a in range(1, maxx + 1):
        for b in lucky_by_a[a]:
            all_lucky.append((a, b))

    # Binary search for min x
    def count_lucky_in_xy(x, y):
        count = 0
        for a, b in all_lucky:
            if a <= x and b <= y:
                count += 1
            elif a > x or b > y:
                break
        return count

    def found_lucky(x, y):
        return count_lucky_in_xy(x, y) >= w

    # Binary search for minimum x * y that satisfies condition
    # Since we want to minimize x*y, we can try increasing x and binary search y
    # But this is complex, so let's use a different approach:
    # Iterate x and find min y for each x

    for x in range(1, maxx + 1):
        # Collect all lucky pairs with a <= x
        x_lucky = [(a, b) for a, b in all_lucky if a <= x]
        if len(x_lucky) < w:
            continue

        # Binary search for min y
        y_low, y_high = 1, maxy
        first_valid = -1

        # Collect b's for x_lucky and sort unique values
        bs = sorted(set(b for a, b in x_lucky if a <= x))
        if not bs:
            continue

        for y in bs:
            if y > maxy:
                break
            # Count how many have b <= y
            count = sum(1 for a, b in x_lucky if b <= y)
            if count >= w:
                first_valid = min(first_valid, x if first_valid == -1 else x)
                break

        if first_valid != -1:
            return f"{x} {y}"

MOD = 10**9 + 7

def power(a, b, m=MOD):
    result = 1
    a %= m
    while b > 0:
        if b % 2 == 1:
            result = (result * a) % m
        a = (a * a) % m
        b //= 2
    return result

def modInverse(a, m=MOD):
    return power(a, m - 2, m)

def solution(input_str):
    import sys
    n, k = map(int, input_str.strip().split())

    if n == 1:
        return "0\n"

    # For i from 1 to n-1, P(I_i = 1) = k^{i + (n - i) - n} = k^{0} = k * k^{-(n-i)}
    # Actually: P(I_i = 1) = k^{-i+2-(n-2i)} = k^{2i - n}

    # Expected value calculation
    # E[f(s)^2] = sum_{i=1}^{n-1} sum_{j=1}^{n-1} k^{n - min(i,j) - i - j + min(i,j)}

    # Simplified: use precomputed factorials and modular inverse
    inv_k = modInverse(k)

