            if i <= j:
                p = n - j - max(0, j - i)
            else:
                p = n - i - max(0, i - j)
            total = (total + power(k, p)) % MOD

    res = power(total, MOD - 2, MOD)
    res = (res * power(power(k, MOD - 2, MOD), -len(str(k))), MOD)

